set -eu
install -d -m 0770 -o named -g named /var/named/dynamic /var/named/data
cat > /etc/named.conf <<'ANTRIEB_NAMED_CONF'
include "/etc/named/infra-update.key";
include "/etc/named/infra-transfer.key";

options {
    listen-on port 53 { any; };
    listen-on-v6 port 53 { none; };
    directory "/var/named";
    dump-file "/var/named/data/cache_dump.db";
    statistics-file "/var/named/data/named_stats.txt";
    memstatistics-file "/var/named/data/named_mem_stats.txt";
    secroots-file "/var/named/data/named.secroots";
    recursing-file "/var/named/data/named.recursing";
    allow-query { any; };
    recursion no;
    minimal-responses yes;
    version "not disclosed";
    pid-file "/run/named/named.pid";
    session-keyfile "/run/named/session.key";
};

logging {
    channel default_debug {
        file "data/named.run";
        severity dynamic;
    };
};

zone "infra.test" IN {
    type primary;
    file "dynamic/infra.test";
    allow-update { key "infra-update"; };
    allow-transfer { key "infra-transfer"; };
    also-notify {
        10.100.102.11 key "infra-transfer";
        10.100.102.12 key "infra-transfer";
    };
    notify yes;
    dnssec-policy default;
    inline-signing yes;
};
ANTRIEB_NAMED_CONF
cat > /var/named/dynamic/infra.test <<'ANTRIEB_ZONE_FILE'
$ORIGIN infra.test.
$TTL 300
@   IN SOA ns1.infra.test. hostmaster.infra.test. (
        2026090201
        60
        30
        1200
        60
)
    IN NS  ns1.infra.test.
    IN NS  ns2.infra.test.
    IN NS  ns3.infra.test.
ns1 IN A   10.100.102.10
ns2 IN A   10.100.102.11
ns3 IN A   10.100.102.12
app IN A   10.100.102.10
status IN TXT "ready"
ANTRIEB_ZONE_FILE
chown root:named /etc/named.conf
chmod 0640 /etc/named.conf
chown named:named /var/named/dynamic/infra.test
chmod 0640 /var/named/dynamic/infra.test
restorecon -RF /etc/named.conf /var/named/dynamic /var/named/data
named-checkconf /etc/named.conf
named-checkzone infra.test /var/named/dynamic/infra.test

